import { test } from "node:test";
import assert from "node:assert/strict";
import { HookBus } from "../src/bus.ts";
import { registerAuditPlugin } from "../src/plugin.ts";

const delay = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

test("handlers run one after another in subscription order", async () => {
  const bus = new HookBus();
  const order: string[] = [];
  bus.on("e", async () => {
    await delay(10);
    order.push("slow");
  });
  bus.on("e", () => order.push("fast"));
  await bus.emit("e", undefined);
  assert.deepEqual(order, ["slow", "fast"]);
});

test("emit resolves only after every handler finished", async () => {
  const bus = new HookBus();
  let finished = false;
  bus.on("e", async () => {
    await delay(10);
    finished = true;
  });
  await bus.emit("e", undefined);
  assert.equal(finished, true);
});

test("a rejecting handler rejects emit and stops the later handlers", async () => {
  const bus = new HookBus();
  const boom = new Error("boom");
  let after = false;
  bus.on("e", () => {});
  bus.on("e", async () => {
    throw boom;
  });
  bus.on("e", () => {
    after = true;
  });
  await assert.rejects(() => bus.emit("e", undefined), (err) => err === boom);
  assert.equal(after, false);
});

test("a throwing handler rejects emit with the same error", async () => {
  const bus = new HookBus();
  const boom = new Error("sync boom");
  bus.on("e", () => {
    throw boom;
  });
  await assert.rejects(() => bus.emit("e", undefined), (err) => err === boom);
});

test("unsubscribing during an emit does not stop the others in that emit", async () => {
  const bus = new HookBus();
  const seen: string[] = [];
  const off = bus.on("e", async () => {
    off();
    seen.push("first");
    await delay(5);
  });
  bus.on("e", () => seen.push("second"));
  await bus.emit("e", undefined);
  assert.deepEqual(seen, ["first", "second"]);
  assert.equal(bus.count("e"), 1);
  await bus.emit("e", undefined);
  assert.deepEqual(seen, ["first", "second", "second"]);
});

test("handlers subscribed during an emit run only from the next emit", async () => {
  const bus = new HookBus();
  const seen: string[] = [];
  bus.on("e", () => {
    bus.on("e", () => seen.push("late"));
    seen.push("first");
  });
  await bus.emit("e", undefined);
  assert.deepEqual(seen, ["first"]);
  await bus.emit("e", undefined);
  assert.deepEqual(seen, ["first", "first", "late"]);
});

test("audit plugin: one-time notice, redaction, then audit log", async () => {
  const bus = new HookBus();
  const audit: string[] = [];
  registerAuditPlugin(bus, audit);
  await bus.emit("tool.after", { tool: "exec", output: "pw password=hunter2 ok" });
  assert.deepEqual(audit, [
    "notice: tool output is audited",
    "exec: pw password=[redacted] ok",
  ]);
  await bus.emit("tool.after", { tool: "read", output: "clean" });
  assert.deepEqual(audit, [
    "notice: tool output is audited",
    "exec: pw password=[redacted] ok",
    "read: clean",
  ]);
});

