// Proves the OLD emit shape (forEach + async callback) causes the three reported symptoms.
type Handler<T> = (payload: T) => void | Promise<void>;

class OldBus {
  private handlers = new Map<string, Handler<unknown>[]>();
  on<T>(event: string, handler: Handler<T>) {
    const list = this.handlers.get(event) ?? [];
    list.push(handler as Handler<unknown>);
    this.handlers.set(event, list);
  }
  async emit<T>(event: string, payload: T): Promise<void> {
    const list = this.handlers.get(event) ?? [];
    list.forEach(async (handler) => {
      await handler(payload);
    });
  }
}

const delay = (ms: number) => new Promise((r) => setTimeout(r, ms));
const bus = new OldBus();
const order: string[] = [];
let rejected: unknown = null;
bus.on("e", async () => {
  await delay(10);
  order.push("slow");
});
bus.on("e", async () => {
  throw new Error("boom");
});
bus.on("e", () => order.push("after-error"));
process.on("unhandledRejection", (e) => {
  rejected = String(e);
});
await bus.emit("e", undefined);
console.log("order right after emit resolved:", JSON.stringify(order));
await delay(30);
console.log("order later:", JSON.stringify(order), "| error surfaced during emit:", rejected);
